"""Render aggregate figures from saved experiment JSONL without rerunning episodes."""
import argparse,json
from pathlib import Path
import matplotlib.pyplot as plt

def wilson(successes,total,z=1.96):
 p=successes/total; den=1+z*z/total; center=(p+z*z/(2*total))/den; margin=z*((p*(1-p)/total+z*z/(4*total*total))**.5)/den; return max(0,center-margin),min(1,center+margin)

def main():
 p=argparse.ArgumentParser();p.add_argument('--input-dir',default='reports/results/week5');p.add_argument('--output-dir',default='reports/figures/week5');a=p.parse_args(); source=Path(a.input_dir); dest=Path(a.output_dir);dest.mkdir(parents=True,exist_ok=True)
 files=list(source.glob('*.jsonl')); records=[]
 for path in files:
  for line in path.read_text().splitlines():
   if line.strip(): records.append(json.loads(line))
 if not records: print('No saved experiment rows found; no figures generated.');return
 strategy=[r for r in records if r.get('experiment')=='strategies']
 if strategy:
  names=sorted({r['strategy'] for r in strategy}); groups=[[r['score'] for r in strategy if r['strategy']==name] for name in names];means=[sum(v)/len(v) for v in groups];errors=[(sum((x-means[i])**2 for x in values)/len(values))**.5/(len(values)**.5) for i,values in enumerate(groups)];plt.figure(figsize=(8,4));plt.bar(names,means,yerr=errors,capsize=4,color='#1c7777');plt.ylabel('Mean terminal vote share (±1 SE)');plt.title(f'Strategy comparison · N={strategy[0]["node_count"]}, n={len(strategy)//len(names)} paired seeds');plt.xticks(rotation=20);plt.tight_layout();plt.savefig(dest/'strategy_score.png',dpi=900);plt.close()
  wins=[sum(r['victory'] for r in strategy if r['strategy']==name) for name in names];sizes=[sum(r['strategy']==name for r in strategy) for name in names];rates=[wins[i]/sizes[i] for i in range(len(names))];intervals=[wilson(wins[i],sizes[i]) for i in range(len(names))];lo=[rates[i]-intervals[i][0] for i in range(len(names))];hi=[intervals[i][1]-rates[i] for i in range(len(names))];plt.figure(figsize=(8,4));plt.errorbar(names,rates,yerr=[lo,hi],fmt='o',capsize=4,color='#c45b38');plt.ylabel('Victory rate (95% Wilson interval)');plt.ylim(0,1.05);plt.title(f'Strategy victory comparison · N={strategy[0]["node_count"]}, n={len(strategy)//len(names)} paired seeds');plt.xticks(rotation=20);plt.tight_layout();plt.savefig(dest/'strategy_victory_rate.png',dpi=900);plt.close()
 budget=[r for r in records if r.get('experiment')=='budget']
 if budget:
  values=sorted({float(r['initial_budget']) for r in budget});counts=[sum(float(r['initial_budget'])==v for r in budget) for v in values];wins=[sum(bool(r['victory']) for r in budget if float(r['initial_budget'])==v) for v in values];rates=[wins[i]/counts[i] for i in range(len(values))];intervals=[wilson(wins[i],counts[i]) for i in range(len(values))];lo=[rates[i]-intervals[i][0] for i in range(len(values))];hi=[intervals[i][1]-rates[i] for i in range(len(values))];plt.figure(figsize=(6,4));plt.errorbar(values,rates,yerr=[lo,hi],fmt='o-',capsize=4,color='#c45b38');plt.xlabel('Initial budget (resource units)');plt.ylabel('Victory rate (95% Wilson interval)');plt.ylim(0,1.05);plt.title(f'Budget sensitivity · N={budget[0]["node_count"]}, paired n={min(counts)} per level');plt.tight_layout();plt.savefig(dest/'budget_victory_rate.png',dpi=900);plt.close()
  score_means=[sum(r['score'] for r in budget if float(r['initial_budget'])==v)/counts[i] for i,v in enumerate(values)];score_se=[(sum((r['score']-score_means[i])**2 for r in budget if float(r['initial_budget'])==v)/counts[i])**.5/(counts[i]**.5) for i,v in enumerate(values)];plt.figure(figsize=(6,4));plt.errorbar(values,score_means,yerr=score_se,fmt='o-',capsize=4,color='#477a65');plt.xlabel('Initial budget (resource units)');plt.ylabel('Mean terminal vote share (±1 SE)');plt.title(f'Mean score vs budget · N={budget[0]["node_count"]}, n={min(counts)} per level');plt.tight_layout();plt.savefig(dest/'budget_mean_score.png',dpi=900);plt.close()
  used=[sum(float(r['budget_used']) for r in budget if float(r['initial_budget'])==v)/counts[i] for i,v in enumerate(values)];plt.figure(figsize=(6,4));plt.plot(values,used,'o-',color='#658cbb');plt.xlabel('Initial budget (resource units)');plt.ylabel('Mean budget spent (resource units)');plt.title(f'Budget use · {budget[0]["strategy"]}, N={budget[0]["node_count"]}, n={min(counts)} per level');plt.tight_layout();plt.savefig(dest/'budget_used.png',dpi=900);plt.close()
 topology=[r for r in records if r.get('experiment')=='topology']
 if topology:
  names=['er','ring_lattice'];groups=[[r['score'] for r in topology if r['topology']==name] for name in names];scores=[sum(v)/len(v) for v in groups];errors=[(sum((x-scores[i])**2 for x in values)/len(values))**.5/(len(values)**.5) for i,values in enumerate(groups)];plt.figure(figsize=(6,4));plt.bar(names,scores,yerr=errors,capsize=4,color=['#658cbb','#62a47c']);plt.ylabel('Mean terminal vote share (±1 SE)');plt.title(f'Topology comparison · N={topology[0]["node_count"]}, paired seeds={len(topology)//2}');plt.tight_layout();plt.savefig(dest/'topology_score.png',dpi=900);plt.close()
  wins=[sum(r['victory'] for r in topology if r['topology']==name) for name in names];sizes=[len(v) for v in groups];rates=[wins[i]/sizes[i] for i in range(2)];intervals=[wilson(wins[i],sizes[i]) for i in range(2)];plt.figure(figsize=(6,4));plt.errorbar(names,rates,yerr=[[rates[i]-intervals[i][0] for i in range(2)],[intervals[i][1]-rates[i] for i in range(2)]],fmt='o',capsize=4,color='#c45b38');plt.ylabel('Victory rate (95% Wilson interval)');plt.ylim(0,1.05);plt.title(f'Topology victory rate · N={topology[0]["node_count"]}, n={sizes[0]} each');plt.tight_layout();plt.savefig(dest/'topology_victory_rate.png',dpi=900);plt.close()
 if strategy:
  chosen=next((r['strategy'] for r in strategy if r['strategy']=='greedy_public_model'),strategy[0]['strategy']); subset=[r for r in strategy if r['strategy']==chosen];horizon=min(len(r['aggregate_support_trajectory']) for r in subset);means=[sum(r['aggregate_support_trajectory'][i] for r in subset)/len(subset) for i in range(horizon)];plt.figure(figsize=(7,4));plt.plot(range(horizon),means,'o-',color='#416c9b');plt.xlabel('Round index');plt.ylabel('Aggregate support (fraction)');plt.ylim(0,1);plt.title(f'Aggregate support trajectory · {chosen}, N={subset[0]["node_count"]}, n={len(subset)}');plt.tight_layout();plt.savefig(dest/'support_trajectory.png',dpi=900);plt.close()
  action_counts={name:sum(action['action_id']==name for r in strategy for action in r['actions']) for name in ('targeted_contact','broadcast','no_op')};plt.figure(figsize=(6,4));plt.bar(action_counts.keys(),action_counts.values(),color='#62a47c');plt.ylabel('Accepted actions across saved episodes');plt.title(f'Campaign action mix · strategy set, N={strategy[0]["node_count"]}, paired n={len(strategy)//len({r["strategy"] for r in strategy})}');plt.tight_layout();plt.savefig(dest/'action_mix.png',dpi=900);plt.close()
 print(f'Read {len(records)} saved result rows from {len(files)} JSONL files; figures in {dest}')
if __name__=='__main__':main()
